"""Q5 Kaggle bootstrap (generated by q5_kaggle_stage.py). MODE/JOB are fixed for this kernel."""
MODE = "full"
JOB = "fed_mixed_iid_baseline_s42"
CODE_SLUG = "q5-fl-code-canonical-v1-20261017"
REL_SHA = "6d2c6b406b329e5016b3244c0079d1ef35103af5e73efe5b0f39c7ce1943d252"
DATASET_ZIP_SHA = "72dd3bc26fd8d427414a95588556ca46054d6befe120a90e88b07dbd569ef557"
import hashlib, json, os, subprocess, sys, zipfile
import time as _t
_T0 = _t.time()
print(json.dumps({"t_s": 0, "stage": "start"}), flush=True)
from pathlib import Path


def sha(p):
    h = hashlib.sha256()
    with open(p, "rb") as fh:
        for b in iter(lambda: fh.read(1 << 20), b""):
            h.update(b)
    return h.hexdigest()


INP = Path(os.environ.get("Q5_KAGGLE_INPUT", "/kaggle/input"))
WS = Path(os.environ.get("Q5_KAGGLE_WORKING", "/kaggle/working")) / "ws"
os.environ.setdefault("Q5_OUT", str(WS.parent / "q5_out"))
man_path = [p for p in INP.rglob("Q5_BUNDLE_MANIFEST.json") if CODE_SLUG in str(p)]
assert len(man_path) == 1, ("code manifest", man_path)
man = json.loads(man_path[0].read_text(encoding="utf-8"))
src = man_path[0].parent
if not WS.exists():
    z = src / man["code_bundle"]["file"]
    if z.is_file():
        assert sha(z) == man["code_bundle"]["sha256"], "code zip sha"
        zipfile.ZipFile(z).extractall(WS)
    else:  # Kaggle auto-extracted the archive: copy members by exact path below the bundle root (q4b patch)
        roots = [p.parents[3] for p in INP.rglob("q5_kaggle.py")
                 if p.parent.as_posix().endswith("experiments/train-improve-20261015/q4a")
                 and (p.parents[3] / "plant_data_contract" / "plant_data_contract" / "CONTRACT_LOCK.json").is_file()]
        assert len(roots) == 1, ("bundle root", [str(r) for r in roots])
        for m in man["code_bundle"]["members"]:
            hit = roots[0].joinpath(*m["path"].split("/"))
            assert hit.is_file(), ("member", m["path"])
            dst = WS / m["path"]
            dst.parent.mkdir(parents=True, exist_ok=True)
            dst.write_bytes(hit.read_bytes())
bad = [m["path"] for m in man["code_bundle"]["members"] if sha(WS / m["path"]) != m["sha256"]]
assert not bad, ("code members differ", bad[:5])
if not (WS / "dataset").exists():
    rm = [p for p in INP.rglob("release_manifest.json") if p.parent.name == "pv_pd_v3" and sha(p) == REL_SHA]
    if rm:
        if os.name == "nt":  # local test only; Kaggle is Linux
            import _winapi
            _winapi.CreateJunction(str(rm[0].parents[2]), str(WS / "dataset"))
        else:
            os.symlink(rm[0].parents[2], WS / "dataset", target_is_directory=True)
    else:
        zips = [p for p in INP.rglob("*.zip") if sha(p) == DATASET_ZIP_SHA]
        assert len(zips) == 1, "no release tree and no dataset zip with the pinned SHA"
        zipfile.ZipFile(zips[0]).extractall(WS)
rel = WS / "dataset/mixed/pv_pd_v3"
assert sha(rel / "release_manifest.json") == REL_SHA
hashes = json.loads((rel / "release_manifest.json").read_text(encoding="utf-8"))["manifest_hashes"]
missing, wrong, n = 0, 0, 0
for split in ("train", "val", "legacy_diagnostic_test", "calibration"):
    assert sha(rel / f"manifests/{split}.jsonl") == hashes[split], ("manifest sha", split)
    for line in open(rel / f"manifests/{split}.jsonl", encoding="utf-8"):
        row = json.loads(line)
        p = WS / "dataset" / row["relative_path"]
        n += 1
        if n % 5000 == 0:
            print(json.dumps({"t_s": round(_t.time() - _T0), "images_checked": n}), flush=True)
        if not p.is_file():
            missing += 1
        elif sha(p) != row["byte_sha256"]:
            wrong += 1
assert missing == 0 and wrong == 0, ("images", n, missing, wrong)
print(json.dumps({"images_verified": n, "missing": missing, "sha_mismatch": wrong}), flush=True)
print(json.dumps({"t_s": round(_t.time() - _T0), "stage": "bootstrap_ok"}), flush=True)
print(json.dumps({"bootstrap": "OK", "mode": MODE, "job": JOB, "code_bundle_sha256": man["code_bundle"]["sha256"]}), flush=True)
args = [MODE] + ([JOB] if JOB else [])
import threading, time  # q4b patch v2: unbuffered driver + heartbeat
HEARTBEAT_S = 300
OUT = Path(os.environ["Q5_OUT"])
T0 = time.time()
DONE = threading.Event()


def heartbeat():
    while not DONE.wait(HEARTBEAT_S):
        logs = sorted(OUT.rglob("*.log"), key=lambda p: p.stat().st_mtime) if OUT.exists() else []
        last, seg = "", None
        if logs:
            seg = logs[-1].relative_to(OUT).as_posix()
            lines = [l.strip() for l in logs[-1].read_text(encoding="utf-8", errors="replace").splitlines() if l.strip()]
            last = lines[-1][-300:] if lines else ""
        rec = {"heartbeat": round(time.time() - T0), "segment": seg, "last": last}
        print(json.dumps(rec), flush=True)
        prog = WS.parent / "PROGRESS.json"
        tmp = prog.with_name("PROGRESS.json.tmp")
        tmp.write_text(json.dumps(rec), encoding="utf-8")
        os.replace(tmp, prog)


threading.Thread(target=heartbeat, daemon=True).start()
rc = subprocess.call([sys.executable, "-B", str(WS / "experiments/train-improve-20261015/q4a/q5_kaggle.py")] + args,
                     env=dict(os.environ, PYTHONUNBUFFERED="1"))
DONE.set()
print(json.dumps({"driver_rc": rc}), flush=True)
sys.exit(rc)
